package com.yibi.backend.entity;

import jakarta.persistence.*;
import lombok.*;
import org.hibernate.annotations.CreationTimestamp;
import org.hibernate.annotations.UpdateTimestamp;

import java.time.LocalDateTime;

/**
 * Vocabulary entity — maps to `vocabulary` table.
 *
 * Data flow:
 * 1. Imported from HSK 3.0 JSON via seed script.
 * 2. pinyin auto-generated by Pinyin4j service on save.
 * 3. hanziTraditional auto-generated by OpenCC4j service on save.
 * 4. audioUrl populated after Azure TTS call → MinIO upload.
 * 5. strokeCount sourced from HSK data; used by hanzi-writer JS.
 */
@Entity
@Table(name = "vocabulary")
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class Vocabulary {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /** Simplified Chinese (简体字), e.g., "学习" */
    @Column(name = "hanzi", nullable = false, length = 20)
    private String hanzi;

    /** Traditional Chinese (繁體字), auto-generated by OpenCC4j, e.g., "學習" */
    @Column(name = "hanzi_traditional", length = 20)
    private String hanziTraditional;

    /** Pinyin with tone marks, auto-generated by Pinyin4j, e.g., "xué xí" */
    @Column(name = "pinyin", nullable = false, length = 100)
    private String pinyin;

    /** Vietnamese meaning */
    @Column(name = "meaning_vi", columnDefinition = "TEXT")
    private String meaningVi;

    /** English meaning */
    @Column(name = "meaning_en", columnDefinition = "TEXT")
    private String meaningEn;

    /** HSK level (1–9 per HSK 3.0 standard) */
    @Column(name = "hsk_level", nullable = false)
    private Integer hskLevel;

    /** Part of speech: noun, verb, adjective, adverb, etc. */
    @Column(name = "part_of_speech", length = 50)
    private String partOfSpeech;

    /** Example sentence in Hanzi */
    @Column(name = "example_sentence", columnDefinition = "TEXT")
    private String exampleSentence;

    /** Pinyin of the example sentence */
    @Column(name = "example_pinyin", columnDefinition = "TEXT")
    private String examplePinyin;

    /**
     * MinIO URL of Azure TTS generated .mp3 audio file.
     * Format: http://localhost:9000/yibi-audio/{filename}.mp3
     * Null until TTS is triggered (Admin action or background job).
     */
    @Column(name = "audio_url", length = 500)
    private String audioUrl;

    /**
     * Total stroke count for hanzi-writer JS animation.
     * Not computed — sourced from HSK dataset.
     */
    @Column(name = "stroke_count")
    private Integer strokeCount;

    @CreationTimestamp
    @Column(name = "created_at", nullable = false, updatable = false)
    private LocalDateTime createdAt;

    @UpdateTimestamp
    @Column(name = "updated_at", nullable = false)
    private LocalDateTime updatedAt;
}
